import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class App {
  // ❌ OLD: With spring-boot-starter-security on the classpath and no
  // explicit configuration, Spring Boot auto-configures a default
  // SecurityFilterChain that:
  //   - requires authentication for EVERY request (default 401/login)
  //   - enables CSRF, security headers, form login, and a generated
  //     password logged at startup
  // This is safe but opaque: a simple health endpoint also gets
  // blocked, and developers often discover the behavior only when
  // requests start failing with 401/403.
}

