import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class SecurityConfig {
  // ✅ NEW: The chain is explicit and ordered — public paths permit all,
  // everything else requires authentication, form login is enabled.
  @Bean
  SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    return http
        .authorizeHttpRequests((auth) -> auth
            .requestMatchers("/public/**", "/health").permitAll() // ✅ NEW
            .anyRequest().authenticated()) // ✅ NEW
        .formLogin(Customizer.withDefaults()) // ✅ NEW
        .build();
  }

  // ✅ NEW: multiple chains can be defined, matched by URL pattern
  @Bean
  SecurityFilterChain apiChain(HttpSecurity http) throws Exception {
    return http
        .securityMatcher("/api/**") // ✅ NEW: this chain handles /api/**
        .csrf(AbstractHttpConfigurer::disable)
        .authorizeHttpRequests((auth) -> auth.anyRequest().permitAll())
        .build();
  }
}
